import '../setup-filesystem-isolation.js';
import assert from 'node:assert/strict';
import {performance,monitorEventLoopDelay} from 'node:perf_hooks';
import {fetchContiguousTimeline} from '../../web/src/ui/timeline-catch-up.js';
import {getTimelineViewportWindow} from '../../web/src/components/timeline.js';
const loop=monitorEventLoopDelay({resolution:1});loop.enable();const cpu=process.cpuUsage(),start=performance.now();let requests=0,rows=0;const results:number[]=[];
for(let repeat=0;repeat<100;repeat++){const at=performance.now();const result=await fetchContiguousTimeline([{id:1}],async(limit:number,before:number|null)=>{requests++;const end=before===null?10000:before-1;rows+=limit;return{posts:Array.from({length:limit},(_,n)=>({id:end-n,data:{content:'synthetic'}})),has_more:true};});assert.equal(result!.posts.length,500);assert.equal(result!.posts.some(row=>row.id===1),false);results.push(performance.now()-at);if(repeat%10===0)await Bun.sleep(5);}
const prefix=Array.from({length:10001},(_,n)=>n*72),rangeStart=performance.now();for(let n=0;n<10000;n++){const result=getTimelineViewportWindow(prefix,(n%9000)*72,1180,false);assert(result.end-result.start>=16);}const windowMs=performance.now()-rangeStart;await Bun.sleep(5);loop.disable();console.log(JSON.stringify({kind:'timeline-catch-up-viewport-helper',repeats:100,pages:requests,rows,catchUpMs:{min:Math.min(...results),max:Math.max(...results),total:results.reduce((a,b)=>a+b,0)},viewport:{calculations:10000,prefixRows:10000,ms:windowMs},wallMs:performance.now()-start,cpuUs:process.cpuUsage(cpu),eventLoop:{samples:loop.count,maxMs:loop.max/1e6,p99Ms:loop.percentile(99)/1e6},memory:process.memoryUsage(),scope:'isolated synthetic helper CPU/bounded worst-case paging; no HTTP/backend/DB/provider/real-message data, no production latency or before-after speed claim'}));
